//Tab active animation
function tabActive(parentEl, el) {
    if ($(parentEl).length && $(el).length) {
        var parentOffset = $(parentEl).offset().left;
        var elOffset = $(el).offset().left - (parentEl !== ".tabs-wrapper" ? (parentOffset - 20) : parentOffset);
        var elWidth = ($(el).width()/$(parentEl).width()) * 100;
        $(parentEl).find(".active-tab").css({ width: elWidth+"%", left: elOffset, visibility: "visible" });
    }
}


