var videoSlider = function(el){
var total = $(el).find(".slide").length;
var current = $("#fullpage .slide.active").index();

function playVideo(){
    if($("#fullpage .slide.active video").length){
        $("#fullpage .slide video").each(function(){
           this.pause();
        });
        $("#fullpage .slide.active video").get(0).play();
    }else{
        $("#fullpage .slide video").each(function(){
            this.pause();
        });
    }
}


function slide(index,prev){
    if(index !== undefined){
        current = index % total;
    }else{
        current = (current + 1) % total;
    }

    prev = $("#fullpage .slide.active").index();
    if($(".intro-tab-content:eq("+current+")").length){
        $(".intro-tab-content").hide();
        $(".intro-tab-content:eq("+current+")").fadeIn(1000);
    }else{
        $(".intro-tab-content").hide();
    }

    tabActive(".section-nav", ".section-nav ul li:eq("+current+")");
     $("#fullpage .slide:eq(" + current + "), .section-nav ul li:eq(" + current + ")").addClass("active").siblings().removeClass("active");
     playVideo();

     console.log("Current "+current + " Prev", prev);

    function slideFrom(currentFrom,prevFrom){

        gsap.fromTo($("#fullpage .slide:eq(" + current + ")"), {x: currentFrom.from,}, {duration: 1.5,x:  currentFrom.to,ease: "power4.inOut"});
        gsap.fromTo($("#fullpage .slide:eq(" + prev + ")"), {x: prevFrom.from}, {duration: 1.5,x: prevFrom.to,ease: "power4.inOut"});
    }

    if(current < prev){
        slideFrom({from:"-100%",to:"0%"},{from:"0%",to:"100%"})
    }else{
        slideFrom({from:"100%",to:"0%"},{from:"0%",to:"-100%"})
    }
}


function init(){
    var introTl = gsap.timeline();
    introTl.set(".content-wrap", { visibility: "visible" });
    introTl.fromTo(".intro-text,.section-nav ul li a", { autoAlpha: 0, y: "100%" }, { delay: 2, stagger: 0.3, duration: 1, autoAlpha: 1, y: "0%", ease: "power4.out" });
    introTl.fromTo(".section-nav .active-tab", { scaleX: 0, transformOrigin: "0% 50%" }, { duration: 1, scaleX: 1, ease: "power4.out" });
    gsap.to("#fullpage .active", {
        duration: 1.5,
        x: "0%",
        ease: "power4.inOut"
    });
    playVideo();
}
  return {
      init: init,
      nextSlide: slide,
      goToSlide: slide
  }

}



