// Locomotive scroll script
if ($('#scrollWrapper').length) {
    $(window).on("load", function() {
        $("[data-scroll-offset]").each(function(){
            var offs = $(this).data("scroll-offset");
            $(this).attr("data-scroll-offset", $(this).offset().top + offs);
        });
        $("[data-custom-offset]").each(function(){
            var offs = $(this).data("custom-offset");
            $(this).attr("data-scroll-offset", offs);
        });
        $("[id]").each(function(){
            $(this).attr("data-offset", $(this).offset().top + $(this).height());
        });
        const target = document.querySelector('#scrollWrapper');
        scroll = new LocomotiveScroll({
            el: target,
            smooth: true,
            getDirection: true,
            repeat: true,
            getSpeed: true
        });
            scroll.on('call', footer => {
                gsap.fromTo(".stone", {autoAlpha:0},{autoAlpha:1,delay:1, duration: 1,stagger:0.5,ease: "power4.out"});

                gsap.to(".stone", {
                    x: "random(-5, 30)",
                    y: "random(-5, 30)",
                    ease: "power1.inOut",
                    duration: 2,
                    repeat: -1,
                    repeatRefresh: true
                  });



            });


        setTimeout(function() {
            // window.scroll.destroy();
            // window.scroll.init();

            var lastScrollTop = 0;
            scroll.on('scroll', (f) => {
                var currentPosition = f.scroll.y;
                //console.log(f);
                var st = currentPosition;
                if (f.direction === "up") {
                    $("body").removeClass("hidden-nav active-nav");
                } else if (f.direction === "down") {
                    $("body").addClass("hidden-nav active-nav");
                }
            });

             function isHeroVisible(){
                 var heroHeight = $(".page-hero,.slide-wrap").outerHeight() - $(".brand-logo").height();
                 var scrollPos = scroll.scroll.instance.scroll.y;
                 if(heroHeight < scrollPos){
                     $("html").addClass("hero-hidden");
                 }else{
                     $("html").removeClass("hero-hidden");
                 }
             }

             isHeroVisible();

             $(window).on("resize", function(){
                isHeroVisible();
             });

             scroll.on('scroll', (el) => {
                isHeroVisible();
             });


            scroll.on('scroll', (el) => {
                if($(".ss").hasClass("is-inview")){
                   var id = $(".ss").data("scroll-target");
                   var offs = $(id).data("offset");
                   var percent = (offs - el.scroll.y) / 105;
                    //console.log(percent)
                   // gsap.set(".ss", {y: percent+"%"})
                }
            })
        }, 1);











    });
}



