// Book Button animation
var indentSize = parseInt($(".book-btn span").css("text-indent"))/14 +"vw";
console.log(indentSize);
var btnTl = gsap.timeline({ paused: true, ease: "power4.out" }).reversed(true);
btnTl.fromTo(".book-btn > span", {textIndent: "-4.5vw"},{ duration: 0.5, textIndent: (30/14)+"vw" }, "pc");
btnTl.to(".book-btn .c-close span i", { stagger: 0.3, duration: 0.3, scaleX: 1 });
btnTl.fromTo(".pop-content", {y:"-100%"},{ duration: 0.7, y: "0%", ease: "power4.out" }, "pc+=0.3");
$(document).on("click", ".book-btn", function() {
    if(btnTl.reversed()){
        btnTl.play();
        if(!$("body").hasClass("home-page")){
            scroll.stop();
        }
    }else{
        btnTl.reverse();
        if(!$("body").hasClass("home-page")){
            scroll.start();
        }
    }
    $("html").toggleClass("active-booknow");
});


