$(document).on("click", ".hm", function() {
    $("html").toggleClass("nav-active");
    if ($("html").hasClass("nav-active")) {
        menuTl.play();
        if(!$("body").hasClass("home-page")){
             window.scroll.stop();
        }

    } else {
        menuTl.reverse("popfade+=0.5");
        menuTl.reversed(true);
        if(!$("body").hasClass("home-page")){
              window.scroll.start();
        }
    }
});


