$(document).on("click", "[data-scrollto]", function(e) {
    e.preventDefault();
    var headerHeight = $(".header-main").outerHeight() - 10;
    var scrollToElm = $(this).data("scrollto");
    var scrollPos = $("#" + scrollToElm).offset().top - headerHeight;
    $("html,body").stop().animate({ scrollTop: scrollPos }, 1000);
    $(".nav-active .hamburger").trigger("click");
});

$(document).on("keyup", function(e) {
    if (e.keyCode === 27) {
        $(".active-booknow .book-btn,.nav-active .hm").trigger("click");
    }
});